        $spec=array('study_state'=>array('id','lifecycle_revision','state','erase_emails','request_id'),'study_state_summary'=>array('id'),'email_template_preview'=>array('entry'),'email_library'=>array(),'email_library_save'=>array('entry','revision'),'email_library_delete'=>array('id','revision'),'list'=>array(),'load'=>array('id'),'create'=>array('administration','request_id'),'save'=>array('id','revision','request_id','definition'),'validate'=>array('id'),'publish'=>array('id','revision','acknowledgements'),'clone'=>array('id','revision'),'retire'=>array('id','revision'),'discard'=>array('id','revision'),'activate'=>array('id','revision','state'),'experience'=>array('id','context','commands'),'simulate'=>array('id','context','commands'),'import'=>array('id','revision','request_id','assessment','template'),'source'=>array('id','assessment'),'templates'=>array(),'email_preview'=>isset($p['definition'])?array('definition'):array(),'native_templates'=>array(),'edit'=>array('id'),'duplicate_study'=>array('id','revision','request_id'),'archive_study'=>array('id','revision'),'delete_study'=>array('study_id','confirmation'));
