            case 'experience':return $s->experience($p['id'],$p['context'],$p['commands']);case 'simulate':return $s->simulate($p['id'],$p['context'],$p['commands']);case 'import':return $s->importTemplate($p['id'],$p['revision'],$p['request_id'],$p['assessment'],$p['template']);case 'source':return $s->templateSource($p['id'],$p['assessment']);
