            case 'email_preview':$t=new \EIPSI\StudyEngine\Longitudinal\EmailTemplate();$v=array('study_name'=>'Estudio de ejemplo','assessment_name'=>eipsi_admin_translate('Assessment'),'available_time'=>'09:00 Europe/Berlin','due_time'=>'09:45 Europe/Berlin','direct_link'=>'https://example.invalid/access','withdrawal_link'=>'https://example.invalid/withdrawal');$templates=isset($p['definition'])?(\EIPSI\StudyEngine\Longitudinal\Configuration::read(Draft::validate($p['definition']))['initial_screen']['templates']??array()):array();$templates=\EIPSI\StudyEngine\Longitudinal\EmailTemplate::configured($templates);return array('verification'=>$t->render('VERIFY_PARTICIPANT',$v,$templates),'availability'=>$t->render('ASSESSMENT_AVAILABLE',$v,$templates),'reminder'=>$t->render('ASSESSMENT_REMINDER',$v,$templates),'catalog_only'=>!isset($p['definition']));
