    public static function ajax(): void {
        try{\EIPSI_Http_Policy::post(admin_url());$raw=wp_unslash($_POST['payload']??'');if(!is_string($raw)||strlen($raw)>2300000)throw new \DomainException('BUILDER_PAYLOAD_LIMIT');$p=json_decode($raw,true,128,JSON_THROW_ON_ERROR);if(!is_array($p))throw new \DomainException('BUILDER_DTO_REQUIRED');$out=self::handle($p,(string)($_POST['nonce']??''));wp_send_json_success($out);}
