    }
    /** Gutenberg itself serializes save markup; server never invents static block HTML. */
    public static function editorAssets(): void {
        Service::authorize();$id=absint($_GET['post']??0);if(!$id||!current_user_can('edit_post',$id)||!get_post_meta($id,'_eipsi_builder_source',true))return;
        $blocks=get_post_meta($id,'_eipsi_builder_source_blocks',true);$base=get_post_meta($id,'_eipsi_builder_source_base_hash',true);if(!is_array($blocks)||!hash_equals((string)$base,hash('sha256',get_post($id)->post_content)))return;
        wp_enqueue_script('eipsi-study-builder-source',EIPSI_FORMS_PLUGIN_URL.'assets/js/study-builder-source.js',array('wp-blocks','wp-data','wp-dom-ready'),EIPSI_FORMS_VERSION,true);
        wp_localize_script('eipsi-study-builder-source','eipsiStudyBuilderSource',array('blocks'=>$blocks,'postId'=>$id));
    }
